import{_ as i,l as n,o as e,c as l,v as t,p as s,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"生产监控与告警","description":"","frontmatter":{"title":"生产监控与告警","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/production-monitoring-alerts.md","filePath":"quant/production-monitoring-alerts.md","lastUpdated":1789023840000}'),E={name:"quant/production-monitoring-alerts.md"};function c(u,a,A,m,B,_){const o=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="生产监控与告警" tabindex="-1">生产监控与告警 <a class="header-anchor" href="#生产监控与告警" aria-label="Permalink to &quot;生产监控与告警&quot;">​</a></h1><div class="epigraph"><p>实盘与回测的差要在分钟级被拆开：行情陈旧、拒单、敞口越权、特征版本漂移。告警是动作，不是仪表盘上的红色装饰。</p><footer>—— Perold, The Implementation Shortfall, JPM, 1988；SEC Knight Capital 处罚令（Release No. 70694）；对照[监控：PnL、敞口、拒单](/quant/trading-telemetry)</footer></div><p><a href="/quant/research-log-discipline">上一课</a>把实验室账本收好。本课的缺口是<strong>上线之后</strong>：生产监控如何接到已有的遥测课，并覆盖本课程特有的对象——特征版本、馈送序号、清算状态、容量。Perold 的实施缺口给出会计对象；Knight 给出变更失败的监管案例。<a href="/quant/trading-telemetry">遥测课</a>已拆 PnL / 敞口 / 拒单；本课补研究栈上线后的告警策略，不重写那三张时间序列的定义。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>回测假设特征版本哈希不变、行情无缺口、成交皆确认、容量按登记的参与率。生产里每一项都会破。问题是把破标记成可分页的告警，并预先绑定动作：停开新仓、只许减仓、切备用行情、回滚特征版本。没有绑定动作的告警会在噪声中被静音，真正的故障（脏行情、错误映像）就会穿过。</p><p>告警要分层：数据（序号缺口、as-of 落后）、模型（特征缺失率、IC 的实时代理异常——谨慎使用）、执行（拒单率、部分成交）、风险（敞口、VM、涨跌停锁仓）、清算（fail、未确认）。全部塞进一个「健康分」会重现遥测课批评过的混加总。</p><h3 id="研究–实盘对账是日课" tabindex="-1">研究–实盘对账是日课 <a class="header-anchor" href="#研究–实盘对账是日课" aria-label="Permalink to &quot;研究–实盘对账是日课&quot;">​</a></h3><p>每日把生产成交与信号快照对账：是否用对特征版本、是否在 stale 簿上发过依赖名次的单、实施缺口各成分。差应归入登记过的成本模型容忍带；超出则开事故，而不是调参数把曲线修平。这与研究日志衔接：生产事故也是实验，要有编号。</p><p><span class="marginnote">A 股还要监控：可卖量违规、程序化报撤形态接近阈值、两融维持担保比例。阈值来自公开规则与会员合同，不是来自夏普。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每个告警：检测统计量、时钟、阈值、抑制（避免行情微缺口刷屏）、升级路径、自动动作。自动动作必须可逆且保守：默认停开。心跳覆盖旁路网卡、特征作业、报盘会话，而不只覆盖策略进程。变更窗口：映像与特征版本发布后进入强化监控，参照 Knight——新版本是先验危险。</p><p>容量监控：实时参与率、借券费率、期货保证金占用，对照登记的容量曲线。接近曲线则降仓，而不是等冲击把当日 PnL 洗掉再解释。后课专门写容量估计，本课只要求监控读那条曲线。</p><h3 id="假阳性与假阴性" tabindex="-1">假阳性与假阴性 <a class="header-anchor" href="#假阳性与假阴性" aria-label="Permalink to &quot;假阳性与假阴性&quot;">​</a></h3><p>过密告警导致静音；过疏导致 Knight 式发现过晚。用历史中断日与故意注入的 stale 行情做演练，统计检测延迟。演练失败则改检测，不改「我们盯着屏幕」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>生产是另一个数据生成过程：延迟、部分成交、人为变更。监控把该过程观测出来，使策略假设可证伪。没有观测，回测纪律全在实验室，实盘变回无日志试错。告警绑定动作，是把<a href="/quant/exchange-outages">故障课</a>的状态机接到运行时。</p><p>特征版本漂移是静默的未来函数反面：训练用 v12，生产误发 v11 或未发布的 v13。哈希比对应在开盘前完成，失败则不准开盘交易。</p>',17)),(e(),s(p,null,{default:r(()=>[h(o,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20Heart%5B%22%E5%BF%83%E8%B7%B3%20%E9%A6%88%E9%80%81%20%E4%BC%9A%E8%AF%9D%20%E4%BD%9C%E4%B8%9A%22%5D%20--%3E%20Det%5B%22%E5%88%86%E5%B1%82%E6%A3%80%E6%B5%8B%22%5D%0A%20%20Det%20--%3E%20Act%5B%22%E7%BB%91%E5%AE%9A%E5%8A%A8%E4%BD%9C%20%E5%81%9C%E5%BC%80%20%2F%20%E5%8F%AA%E5%87%8F%20%2F%20%E5%88%87%E6%BA%90%22%5D%0A%20%20Rec%5B%22%E6%97%A5%E7%BB%88%E5%AF%B9%E8%B4%A6%20%E7%89%88%E6%9C%AC%E4%B8%8E%E7%BC%BA%E5%8F%A3%22%5D%20--%3E%20Inc%5B%22%E4%BA%8B%E6%95%85%E7%BC%96%E5%8F%B7%20%E5%86%99%E5%85%A5%E6%97%A5%E5%BF%97%22%5D%0A%20%20Act%20--%3E%20Rec%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不提供绕过告警继续交易、或把监管报撤监控当成可优化的「距离阈值还有多远」的交易策略。告警阈值若来自交易所规则，只能留安全边际，不能贴线运行。本课不替代会员与合规的官方监控。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>告警必须绑定保守动作；健康分不能混加总数据、执行与清算。</li><li>每日对账特征版本与实施缺口；变更窗口强化监控。</li><li>容量与制度约束（可卖量、两融、报撤）进入同一套分页。</li><li>出处：Perold, <em>JPM</em>, 1988；SEC Release No. 70694；本栏遥测课。</li></ul>',4))])}const P=i(E,[["render",c]]);export{q as __pageData,P as default};
